export function getTweaksByCategory(cat: string) { return tweaks.filter(t => t.category === cat) }
export function getTweaksByCategoryAndTab(cat: string, tab: string) { return tweaks.filter(t => t.category === cat && t.tab === tab) }
export function getSafeTweaks() { return tweaks.filter(t => t.risk === 'safe') }
